const A = E.a;
const B = E.b;
/** Reveal driven by the scene length, so the reveal order holds whatever the narration timing turns out to be. */
const rv = (t: number, dur: number, a: number, b: number) => ep(t, a * dur, b * dur);
/** Glue each flag to its value with a no-break space, so a wrapped command breaks between flag pairs. */
const nb = (s: string) => s.replace(/(-[A-Za-z_:]+) (?=[^-\s])/g, '$1\u00a0');
const bytes = (n: number) => n.toLocaleString('en-US');
const B_ = (n: number) => `${bytes(n)} B`;

/* ------------------------------------------------------------------ local timeline (vertical sizes) */

const X0 = 60;
const X1 = 940;
type Span = {from: number; to: number; color: string; row?: number; label?: string; outside?: boolean; o?: number; g?: number};
type Mark = {at: number; color?: string; label?: string; h?: number; side?: 'top' | 'bottom'; o?: number; off?: number};

const VTrack: React.FC<{y: number; max: number; min?: number; title?: string; titleColor?: string; ticks?: number[]; tickFmt?: (v: number) => string; kf?: number[]; kfLabel?: (v: number) => string; kfColor?: string; spans?: Span[]; marks?: Mark[]; rows?: number; o?: number}> = ({y, max, min = 0, title, titleColor, ticks = [], tickFmt = (v) => String(v), kf = [], kfLabel = (v) => String(v), kfColor, spans = [], marks = [], rows, o = 1}) => {
  const x = (v: number) => X0 + ((v - min) / (max - min)) * (X1 - X0);
  const nRows = rows ?? Math.max(1, ...spans.map((s) => (s.row ?? 0) + 1));
  const kc = kfColor ?? C.cyan;
  const RH = 64;
  return (
    <div style={{position: 'absolute', left: 0, top: 0, width: 0, height: 0, opacity: o, fontFamily: F.mono}}>
      {title && <div style={{position: 'absolute', left: X0, top: y + 62, width: X1 - X0, fontFamily: F.sans, fontSize: 30, fontWeight: 700, color: titleColor ?? C.dim, whiteSpace: 'nowrap'}}>{title}</div>}
      <div style={{position: 'absolute', left: X0, top: y, width: X1 - X0, height: 5, background: C.mute, borderRadius: 2}} />
      {ticks.filter((v) => !kf.includes(v)).map((v) => (
        <React.Fragment key={`t${v}`}>
          <div style={{position: 'absolute', left: x(v) - 1.5, top: y, width: 3, height: 16, background: C.mute}} />
          <div style={{position: 'absolute', left: x(v) - 70, top: y + 22, width: 140, textAlign: 'center', fontSize: 26, color: C.dim, whiteSpace: 'nowrap'}}>{tickFmt(v)}</div>
        </React.Fragment>
      ))}
      {spans.map((s, i) => {
        const wpx = Math.max(8, (x(s.to) - x(s.from)) * (s.g ?? 1));
        return (
          <div key={`s${i}`} style={{position: 'absolute', left: x(s.from), top: y - RH * ((s.row ?? 0) + 1), width: wpx, height: 52, opacity: s.o ?? 1, boxSizing: 'border-box', borderRadius: 10, background: `${s.color}40`, border: `4px solid ${s.color}`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.text, fontSize: 26, fontWeight: 700, whiteSpace: 'nowrap'}}>
            {!s.outside && s.label}
            {s.outside && s.label && <span style={{position: 'absolute', left: wpx + 12, color: s.color, fontFamily: F.sans, fontSize: 30, fontWeight: 700}}>{s.label}</span>}
          </div>
        );
      })}
      {marks.map((m, i) => {
        const h = m.h ?? RH * nRows + 20;
        const bottom = m.side === 'bottom';
        const lx = Math.min(X1 - 190, Math.max(X0 + 190, x(m.at)));
        return (
          <React.Fragment key={`m${i}`}>
            <div style={{position: 'absolute', left: x(m.at) - 2, top: bottom ? y + (m.off ?? 0) : y - h, width: 0, height: h + 14, borderLeft: `4px dashed ${m.color ?? C.red}`, opacity: m.o ?? 1}} />
            {m.label && <div style={{position: 'absolute', left: lx - 190, top: bottom ? y + (m.off ?? 0) + h + 22 : y - h - 46, width: 380, textAlign: 'center', fontFamily: F.sans, fontSize: 30, fontWeight: 700, color: m.color ?? C.red, whiteSpace: 'nowrap', opacity: m.o ?? 1}}>{m.label}</div>}
          </React.Fragment>
        );
      })}
      {kf.map((v) => (
        <React.Fragment key={`k${v}`}>
          <div style={{position: 'absolute', left: x(v) - 13, top: y - 10, width: 26, height: 26, background: kc, transform: 'rotate(45deg)', borderRadius: 4, border: `4px solid ${C.bg}`, boxSizing: 'border-box'}} />
          {kfLabel(v) !== '' && <div style={{position: 'absolute', left: x(v) - 70, top: y + 24, width: 140, textAlign: 'center', fontSize: 26, fontWeight: 700, color: kc, whiteSpace: 'nowrap'}}>{kfLabel(v)}</div>}
        </React.Fragment>
      ))}
    </div>
  );
};

